import { effectiveCost, nodeById } from './graph'
import { RoutingEngine, label, usableDirect } from './routing'
import type { RoutingAlgorithm, Topology } from './types'

/**
 * traceroute and ICMP behaviour, derived from the forwarding tables of the
 * selected algorithm. Latency numbers are simulated, never measured.
 */

export const RTT_DISCLAIMER =
  'Round-trip times below are generated by this simulator from link costs. No real packet crossed a real network.'

export type TracerouteScenario =
  | 'success'
  | 'unreachable'
  | 'ttl-too-small'
  | 'filtered-router'
  | 'loop'

export interface TracerouteHop {
  ttl: number
  responded: boolean
  nodeId: string | null
  nodeLabel: string | null
  address: string | null
  asNumber?: number
  rtts: number[]
  outcome: 'time-exceeded' | 'echo-reply' | 'no-response' | 'destination-unreachable' | 'expired'
  note: string
}

export interface TracerouteResult {
  from: string
  to: string
  algorithm: RoutingAlgorithm
  scenario: TracerouteScenario
  path: string[]
  hops: TracerouteHop[]
  reached: boolean
  stoppedByTtl: boolean
  maxTtl: number
  probesPerHop: number
  summary: string
  detail: string
  baseHeader: string
}

export interface TracerouteInput {
  topology: Topology
  algorithm: RoutingAlgorithm
  fromId: string
  toId: string
  probesPerHop?: number
  maxTtl?: number
  scenario?: TracerouteScenario
  /** Router id that stays quiet (models a filtered / non-responding hop). */
  silentRouterId?: string
  /** Cyclic path used to demonstrate a loop that only TTL kills. */
  loopPath?: string[]
}

/** Router-level forwarding path for a source/destination pair. */
export function computeForwardingPath(
  topology: Topology,
  algorithm: RoutingAlgorithm,
  fromId: string,
  toId: string
): { path: string[]; links: string[]; cost: number; unreachable: boolean; reason: string } {
  const engine = new RoutingEngine(topology, algorithm)
  const path: string[] = [fromId]
  const links: string[] = []
  let cursor = fromId
  let cost = 0
  const start = nodeById(topology, fromId)
  if (start && start.kind !== 'router' && start.gateway) {
    const link = usableDirect(topology, start.id, start.gateway)
    if (link) {
      path.push(start.gateway)
      links.push(link.id)
      cost += effectiveCost(link)
      cursor = start.gateway
    } else {
      return { path, links, cost, unreachable: true, reason: `${start.label} cannot reach its gateway ${label(topology, start.gateway)}.` }
    }
  }

  const seen: Record<string, number> = {}
  for (let step = 0; step < topology.nodes.length * 3; step += 1) {
    if (cursor === toId) return { path, links, cost, unreachable: false, reason: 'Reached the destination.' }
    const decision = engine.decide(cursor, toId)
    if (!decision.nextHop) {
      return { path, links, cost, unreachable: true, reason: decision.rationale }
    }
    const link = usableDirect(topology, cursor, decision.nextHop)
    if (!link) return { path, links, cost, unreachable: true, reason: `${label(topology, cursor)} points at ${label(topology, decision.nextHop)} with no usable link.` }
    seen[decision.nextHop] = (seen[decision.nextHop] ?? 0) + 1
    if (seen[decision.nextHop]! > 2) {
      return { path, links, cost, unreachable: true, reason: 'Forwarding loop detected while building the path.' }
    }
    path.push(decision.nextHop)
    links.push(link.id)
    cost += effectiveCost(link)
    cursor = decision.nextHop
  }
  return { path, links, cost, unreachable: true, reason: 'The walk never terminated.' }
}

/**
 * Deterministic simulated RTT. It is a function of link cost only, so a rerun
 * of the same experiment always prints the same numbers.
 */
export function simulatedRtt(baseCost: number, ttl: number, probe: number): number {
  const jitter = ((ttl * 31 + probe * 17) % 7) * 0.07
  return Math.round((0.6 + baseCost * 1.15 + jitter) * 100) / 100
}

export function runTraceroute(input: TracerouteInput): TracerouteResult {
  const topology = input.topology
  const probes = input.probesPerHop ?? 3
  const scenario: TracerouteScenario = input.scenario ?? 'success'
  const computed = computeForwardingPath(topology, input.algorithm, input.fromId, input.toId)

  let path = computed.path
  let unreachable = computed.unreachable
  let forcedLoop = false

  if (scenario === 'loop' && input.loopPath?.length) {
    path = input.loopPath
    unreachable = true
    forcedLoop = true
  } else if (scenario === 'unreachable') {
    path = path.slice(0, Math.max(1, path.length - 1))
    unreachable = true
  } else if (scenario === 'filtered-router') {
    unreachable = computed.unreachable
  } else {
    unreachable = computed.unreachable
  }

  // TTL 1 expires at the first device *downstream* of the sender, so the source
  // itself is never a traceroute respondent.
  const probeTargets = path.slice(1)
  const maxTtl = input.maxTtl ?? Math.max(6, probeTargets.length + 2)
  const hops: TracerouteHop[] = []
  const src = nodeById(topology, input.fromId)
  const dst = nodeById(topology, input.toId)

  for (let ttl = 1; ttl <= maxTtl; ttl += 1) {
    const responderId = probeTargets[ttl - 1] ?? null
    const isFinal = responderId !== null && responderId === probeTargets.at(-1) && !unreachable

    if (responderId === null) {
      hops.push({
        ttl,
        responded: false,
        nodeId: null,
        nodeLabel: null,
        address: null,
        rtts: Array(probes).fill(0),
        outcome: 'expired',
        note: forcedLoop
          ? 'No reply within the TTL budget — the probes kept circling.'
          : 'Beyond the destination: nothing answered at this TTL, which is what a completed traceroute looks like at the end.',
      })
      continue
    }

    const node = nodeById(topology, responderId)
    const address = node?.ip ?? null
    const previousId = path[ttl - 1] ?? responderId
    const linkCost = effectiveCostOr(topology, previousId, responderId)
    const rtts = Array.from({ length: probes }, (_, probe) => simulatedRtt(linkCost, ttl, probe))
    const silent = scenario === 'filtered-router' && responderId === (input.silentRouterId ?? null)

    if (silent) {
      hops.push({
        ttl,
        responded: false,
        nodeId: responderId,
        nodeLabel: node?.label ?? responderId,
        address,
        asNumber: node?.asNumber,
        rtts: Array(probes).fill(0),
        outcome: 'no-response',
        note: `${node?.label ?? responderId} forwarded the probe but sent no ICMP reply — a filtered or unconfigured router. traceroute prints asterisks and keeps going.`,
      })
      continue
    }

    if (scenario === 'unreachable' && responderId === probeTargets.at(-1)) {
      hops.push({
        ttl,
        responded: true,
        nodeId: responderId,
        nodeLabel: node?.label ?? responderId,
        address,
        asNumber: node?.asNumber,
        rtts,
        outcome: 'destination-unreachable',
        note: `${node?.label ?? responderId} has no route onward, so it answers ICMP Destination Unreachable (Type 3) instead of Time Exceeded. traceroute stops and reports the failure.`,
      })
      break
    }

    if (isFinal) {
      hops.push({
        ttl,
        responded: true,
        nodeId: responderId,
        nodeLabel: node?.label ?? responderId,
        address,
        asNumber: node?.asNumber,
        rtts,
        outcome: 'echo-reply',
        note: `${node?.label ?? responderId} is the destination: it replies to the probe instead of forwarding it, which tells traceroute to stop.`,
      })
      break
    }

    hops.push({
      ttl,
      responded: true,
      nodeId: responderId,
      nodeLabel: node?.label ?? responderId,
      address,
      asNumber: node?.asNumber,
      rtts,
      outcome: 'time-exceeded',
      note: forcedLoop
        ? `${node?.label ?? responderId} answered with ICMP Time Exceeded. It has already appeared on this list — the probe is circling.`
        : `${node?.label ?? responderId} decremented TTL to ${ttl - 1 === 0 ? 0 : 'a positive value'}, let the probe expire and returned ICMP Time Exceeded (Type 11, Code 0) carrying its own address.`,
    })
  }

  const reached = !unreachable && hops.at(-1)?.outcome === 'echo-reply'
  const stoppedByTtl = !reached
  const loopDetected = forcedLoop || new Set(path.slice(0, path.length - (unreachable ? 0 : 1))).size !== path.length

  return {
    from: src?.label ?? input.fromId,
    to: dst?.label ?? input.toId,
    algorithm: input.algorithm,
    scenario,
    path,
    hops,
    reached,
    stoppedByTtl,
    maxTtl,
    probesPerHop: probes,
    summary: describeOutcome(reached, scenario, hops.length, maxTtl, loopDetected),
    detail: buildDetail(reached, scenario, path, hops, unreachable, computed.reason, loopDetected),
    baseHeader: `${hops.length} TTL probe round(s), ${probes} probe(s) per hop, ${RTT_DISCLAIMER}`,
  }
}

function describeOutcome(
  reached: boolean,
  scenario: TracerouteScenario,
  hopCount: number,
  maxTtl: number,
  loop: boolean
): string {
  if (reached) return `Destination reached in ${hopCount} hop(s).`
  if (scenario === 'loop' || loop) return `No destination reply: the probes circled until the TTL budget of ${maxTtl} ran out.`
  if (scenario === 'ttl-too-small' || hopCount >= maxTtl) return `Traceroute stopped at the configured maximum TTL of ${maxTtl} without reaching the destination.`
  if (scenario === 'unreachable') return 'The last responsive router reported ICMP Destination Unreachable instead of forwarding onward.'
  return `Path incomplete after ${hopCount} hop(s).`
}

function buildDetail(
  reached: boolean,
  scenario: TracerouteScenario,
  path: string[],
  hops: TracerouteHop[],
  unreachable: boolean,
  reason: string,
  loop: boolean
): string {
  if (reached) {
    return `traceroute walks the ${path.map((id) => id).length}-node forwarding path produced by the simulation: ${path.join(' → ')}. Each row is one TTL value, so the router that answers is exactly the router at that hop distance.`
  }
  if (scenario === 'loop' || loop) {
    return `A forwarding loop repeats a router on the path. traceroute shows the same address at increasing TTLs and never gets an echo reply; only the TTL expiry in the packet header stops the traffic. This is the classic symptom of inconsistent routing tables.`
  }
  if (scenario === 'ttl-too-small') {
    return `The maximum TTL (${hops.length}) never reached the destination, so the last answer came from an intermediate router. Real traceroute keeps raising TTL until the destination answers or the limit is hit.`
  }
  if (scenario === 'unreachable' || unreachable) {
    return `${reason} traceroute therefore prints the hops it could resolve and reports no destination reply.`
  }
  return `No destination reply was produced. Last responder: ${hops.at(-1)?.nodeLabel ?? 'none'}.`
}

function effectiveCostOr(topology: Topology, a: string, b: string): number {
  const link = usableDirect(topology, a, b)
  return link ? effectiveCost(link) : 1
}

/** ping, expressed with the same simulated latencies. */
export function simulatePing(input: {
  topology: Topology
  algorithm: RoutingAlgorithm
  fromId: string
  toId: string
  count?: number
}): { sent: number; received: number; loss: number; min: number; max: number; avg: number; rttTotal: number; lines: string[]; disclaimer: string } {
  const count = input.count ?? 4
  const route = computeForwardingPath(input.topology, input.algorithm, input.fromId, input.toId)
  const lines: string[] = []
  const rtts: number[] = []
  if (route.unreachable) {
    for (let i = 0; i < count; i += 1) lines.push(`Request could not reach ${nodeById(input.topology, input.toId)?.label ?? input.toId}. (${route.reason})`)
    return { sent: count, received: 0, loss: 100, min: 0, max: 0, avg: 0, rttTotal: 0, lines, disclaimer: RTT_DISCLAIMER }
  }
  for (let i = 0; i < count; i += 1) {
    const rtt = simulatedRtt(route.cost, i + 1, i)
    rtts.push(rtt)
    const dst = nodeById(input.topology, input.toId)
    lines.push(
      `64 bytes from ${dst?.ip ?? dst?.label ?? input.toId}: icmp_seq=${i + 1} ttl=${Math.max(1, 64 - route.path.length + 1)} time=${rtt.toFixed(2)} ms`
    )
  }
  const min = Math.min(...rtts)
  const max = Math.max(...rtts)
  const avg = rtts.reduce((a, b) => a + b, 0) / rtts.length
  return {
    sent: count,
    received: count,
    loss: 0,
    min,
    max,
    avg,
    rttTotal: route.cost,
    lines,
    disclaimer: RTT_DISCLAIMER,
  }
}

export const ICMP_MESSAGES: { type: string; code: string; when: string }[] = [
  { type: 'Echo Request (8)', code: '0', when: 'ping sends this; the target answers with Echo Reply.' },
  { type: 'Echo Reply (0)', code: '0', when: 'Confirms reachability and carries the round-trip time.' },
  { type: 'Destination Unreachable (3)', code: '0 net / 1 host / 3 port / 4 fragmentation needed', when: 'No route, the host is down, the port is closed, or DF=1 blocked fragmentation.' },
  { type: 'Time Exceeded (11)', code: '0 ttl / 1 fragment reassembly', when: 'A router dropped the packet because TTL hit 0 — the message traceroute depends on.' },
  { type: 'Redirect (5)', code: '0 network / 1 host', when: 'A router tells the sender there is a better first-hop router on the same subnet.' },
]
